import{_ as a,o,c as e,a5 as n}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"使用本站程序过程如果遇到问题请查看该文章说明","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["网站通知"],"标签":["softbangong","soft办公","使用问题","程序说明","遇到问题","问题说明"]},"headers":[],"relativePath":"md/网站通知/使用本站程序过程如果遇到问题请查看该文章说明.md","filePath":"md/网站通知/使用本站程序过程如果遇到问题请查看该文章说明.md"}'),r={name:"md/网站通知/使用本站程序过程如果遇到问题请查看该文章说明.md"};function p(s,t,l,h,_,c){return o(),e("div",null,[...t[0]||(t[0]=[n('<h3 id="_1、bat程序中文乱码问题" tabindex="-1">1、Bat程序中文乱码问题 <a class="header-anchor" href="#_1、bat程序中文乱码问题" aria-label="Permalink to &quot;1、Bat程序中文乱码问题&quot;">​</a></h3><p>可能部分程序在复制过程中由于系统编码不一致导致的文件编码变化导致的</p><p>使用记事本打开 .bat 文件，查看如果右下角显示如果所示UTF-8，则使用另存的方式修改</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250228143507174072450739886.png" alt=""></p><p>通过另存的方式将编码格式修正为 ANSI 编码格式</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250228143839174072471995941.png" alt=""></p><h3 id="_2、哪个是bat程序文件" tabindex="-1">2、哪个是bat程序文件 <a class="header-anchor" href="#_2、哪个是bat程序文件" aria-label="Permalink to &quot;2、哪个是bat程序文件&quot;">​</a></h3><p>按照下方图片所示显示程序扩展名，<strong>其他系统可以百度查询怎样显示文件扩展名</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250228144058174072485869100.png" alt=""></p><p>如下图所示的文件为 bat 程序文件</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250228144144174072490422932.png" alt=""></p><h3 id="_3、批量解压缩文件使用" tabindex="-1">3、批量解压缩文件使用 <a class="header-anchor" href="#_3、批量解压缩文件使用" aria-label="Permalink to &quot;3、批量解压缩文件使用&quot;">​</a></h3><p>每个程序都做了相关配置说明，请按照每个程序所在文章的详细说明进行相关操作，先看教程或说明，在动手一般是不会出错的。</p><h3 id="_4、excell类说明" tabindex="-1">4、Excell类说明 <a class="header-anchor" href="#_4、excell类说明" aria-label="Permalink to &quot;4、Excell类说明&quot;">​</a></h3><p>有些人使用的是微软office程序，有些人使用的是wps等程序</p><p>VBA代码在微软office中表现是最好的，wps有些时候可能会出现一些问题，但基本上都可以使用。</p><p><strong>wps使用VBA时需要特别安装一个VBA宏的插件，可以查看该链接：<a href="https://www.softbangong.top/?id=367" target="_blank" rel="noreferrer">https://www.softbangong.top/?id=367</a></strong></p><p>如果使用office则建议使用的版本是office2010版本，这个版本也是测试写VBA时在使用的，比较稳定</p><p><strong>office2010版本下载：</strong></p><p>通过网盘分享的文件：1202<br> 链接: <a href="https://pan.baidu.com/s/1VoiwDaBIYmhMWsAtFadfAw?pwd=67tt" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1VoiwDaBIYmhMWsAtFadfAw?pwd=67tt</a> 提取码: 67tt</p><p>压缩包解压密码：fyvhtIGRp5EEekjTQ62NhfnPh9tGDX</p><h3 id="_5、exe程序使用问题" tabindex="-1">5、Exe程序使用问题 <a class="header-anchor" href="#_5、exe程序使用问题" aria-label="Permalink to &quot;5、Exe程序使用问题&quot;">​</a></h3><p>正常从官网下载安装的系统一般是不会出现问题的，如果电脑中有安装一些杀毒软件，使用时放行即可，软件确保无毒、安全。</p><p>有些人电脑是使用的一些第三方工具进行重做的系统，可能存在一些问题比如某些功能不全、运行程序时提示丢失 dll 文件等问题，可以使用该工具修复下：<a href="https://www.softbangong.com/1565.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1565.html</a></p><p>有些人的电脑可能会出现缺失某某库，可以使用该工具修复下：<a href="https://www.softbangong.com/1584.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1584.html</a></p><p><strong>其他一般正常从正规渠道安装的系统是不会出现问题的，所有程序除特别说明的外都只支持windows7及以上64位操作系统</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1578.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1578.html</a></p>',28)])])}const w=a(r,[["render",p]]);export{g as __pageData,w as default};
